package pipewire

import (
	"bytes"
	"encoding/hex"
	"testing"
)

// Bytes libspa's spa_pod_builder writes for the same params (PipeWire
// 1.0.5, built with gcc on linux/amd64).
const (
	specEnumFormatDMABuf = ""
	specEnumFormatShm    = ""
	specBuffersDMABuf    = "200000000f0000000400040005000000060000000000000004000000040000000800000000000000"
	specFormatFixed      = ""
)

func TestPODsMatchLibspa(t *testing.T) {
	for _, c := range []struct {
		name string
		got  []byte
		want string
	}{
		{"EnumFormat with a linear modifier", enumFormat(1920, 1080, 60, []int64{0}), specEnumFormatDMABuf},
		{"EnumFormat for shared memory", enumFormat(1920, 1080, 60, nil), specEnumFormatShm},
		{"Buffers of DMA-BUFs", buffersParam(1 << dataDmaBuf), specBuffersDMABuf},
	} {
		want, _ := hex.DecodeString(c.want)
		if !bytes.Equal(c.got, want) {
			t.Errorf("%s:\n got %x\nwant %x", c.name, c.got, want)
		}
	}
}

func TestParseFormat(t *testing.T) {
	b, _ := hex.DecodeString(specFormatFixed)
	f, err := parseFormat(b)
	if err != nil {
		t.Fatal(err)
	}
	if f.format != videoBGRx || f.width != 2560 || f.height != 1440 || !f.hasModifier || f.modifier != 0 {
		t.Fatalf("%+v", f)
	}
	// Our own EnumFormat parses to its defaults: the first choice of each.
	f, err = parseFormat(enumFormat(1280, 720, 60, nil))
	if err != nil || f.format != videoBGRx || f.width != 1280 || f.height != 720 || f.hasModifier {
		t.Fatalf("%+v %v", f, err)
	}
	if _, err := parseFormat(b[:40]); err == nil {
		t.Fatal("a cut format parsed")
	}
}
